import javax.net.ssl.*;
import java.io.*;
import java.net.*;
public class HttpsCheck {
  public static void main(String[] args) {
    String[] urls = new String[] {
      "https://google.com","https://github.com","https://cloudflare.com",
      "https://wikipedia.org","https://example.com","https://1.1.1.1"
    };
    if (args.length > 0) urls = args;
    for (String u : urls) {
      HttpURLConnection c = null;
      try {
        URL url = new URL(u);
        c = (HttpURLConnection) url.openConnection();
        c.setConnectTimeout(12000);
        c.setReadTimeout(12000);
        c.setRequestProperty("User-Agent","zen-test");
        c.connect();
        int code = c.getResponseCode();
        System.out.println(u + " -> HTTP " + code + " " + c.getResponseMessage());
      } catch (Exception e) {
        System.out.println(u + " -> ERROR " + e.getClass().getSimpleName() + ": " + e.getMessage());
      } finally {
        if (c != null) c.disconnect();
      }
    }
  }
}
EOF
