       <button class="btn" onclick="testNotification()">Тест уведомления</button>
       <button class="btn btn-primary" onclick="launchExtensionWindow()">Запустить расширение</button>
+        <button class="btn" onclick="window.open('/code-runner.html','_blank')">Запуск кода (JS/PY)</button>
       <button class="btn" onclick="toggleBrowsec()">Browsec</button>
       <span id="browsec-status" style="margin-left: 12px; color: #8899a3; font-size: 12px;">—</span>
