   <script>
     'use strict';

     // Проверка поддержки Service Worker
     if ('serviceWorker' in navigator) {
       navigator.serviceWorker.register('/sw.js').then(function(registration) {
         console.log('SW зарегистрирован:', registration.scope);
       });
     }

     // Проверка поддержки уведомлений
     function testNotification() {
       if (!('Notification')) {
         alert('Уведомления не поддерживаются');
         return;
       }
       if (Notification.permission === 'default') {
         Notification.requestPermission().then(function(result) {
           if (result === 'granted') {
             new Notification('Zen Panel PWA', {
               body: 'Приложение работает без Chrome браузера!',
               icon: '/icons/icon-192x192.png'
             });
           }
         });
       } else if (Notification.permission === 'granted') {
         new Notification('Zen Panel PWA', {
           body: 'Уведомления включены!',
           icon: '/icons/icon-192x192.png'
         });
       }
     }

     // Проверка статуса
     function checkStatus() {
       if (navigator.onLine) {
         document.getElementById('status').textContent = 'Онлайн';
         document.getElementById('status').className = 'status online';
       } else {
         document.getElementById('status').textContent = 'Офлайн';
         document.getElementById('status').className = 'status offline';
       }
     }

     window.addEventListener('online', checkStatus);
     window.addEventListener('offline', checkStatus);
     checkStatus();

     // Нативная Google Search
     function doGoogleSearch() {
       var input = document.getElementById('searchInput');
       var query = input.value.trim();
       if (query) {
         var searchUrl = 'https://www.google.com/search?q=' + encodeURIComponent(query);
         // Проброс трафика через Service Worker
         if ('serviceWorker' in navigator) {
           navigator.serviceWorker.ready.then(function(registration) {
             registration.active.postMessage({
               type: 'forward-traffic',
               url: searchUrl
             });
           });
         }
         // Открыть в новом "окне" (вкладке)
         window.open(searchUrl, '_blank');
         input.value = '';
       }
     }

     // Browsec integration
     function toggleBrowsec() {
       // В PWA нельзя напрямую управлять расширением,
       // но можно инициировать запрос через SW с пометкой Browsec
       if ('serviceWorker' in navigator) {
         navigator.serviceWorker.ready.then(function(registration) {
           registration.active.postMessage({
             type: 'toggle-browsec',
             action: 'toggle'
           });
         });
       }
       // Обновляем UI
       updateBrowsecUI();
     }

     function updateBrowsecUI() {
       // Симулируем проверку статуса Browsec
       // В реальности это был бы запрос к расширению
       var browsecSpan = document.getElementById('browsec-status');
       var isActive = Math.random() > 0.5; // Пока что симуляция
       browsecSpan.textContent = isActive ? 'Активен' : 'Отключен';
       browsecSpan.style.color = isActive ? '#4c1' : '#666';
     }

     // Симуляция запуска расширения
     function launchExtensionWindow() {
       // В PWA нельзя использовать chrome.windows.create,
       // но можно открыть новое окно/вкладку с особенностями расширения
       var extWindow = window.open(
         '/extension-simulator.html',
         '_blank',
         'width=800,height=600,titlebar=no,toolbar=no'
       );

       if (extWindow) {
         // Отправка сообщения в новое окно
         extWindow.postMessage({ type: 'init-extension' }, '*');
       }
     }

     // Обработчик сообщений от Service Worker
     window.addEventListener('message', function(event) {
       if (event.data && event.data.type === 'traffic-status') {
         showTrafficStatus(event.data.status);
       }
       if (event.data && event.data.type === 'browsec-status') {
         updateBrowsecStatusUI(event.data.status);
       }
     });

     function showTrafficStatus(status) {
       var statusDiv = document.createElement('div');
       statusDiv.style.padding = '12px';
       statusDiv.style.background = status === 'allowed' ? '#1f2326' : '#3e2525';
       statusDiv.style.borderRadius = '6px';
       statusDiv.style.marginTop = '20px';
       statusDiv.textContent = 'Трафик: ' + status;
       document.querySelector('.container').appendChild(statusDiv);
     }

     function updateBrowsecStatusUI(status) {
       var browsecSpan = document.getElementById('browsec-status');
       if (status === 'connected') {
         browsecSpan.textContent = 'Активен';
         browsecSpan.style.color = '#4c1';
       } else if (status === 'disconnected') {
         browsecSpan.textContent = 'Отключен';
         browsecSpan.style.color = '#666';
       } else {
         browsecSpan.textContent = '—';
         browsecSpan.style.color = '#8899a3';
       }
     }
   </script>
